                          'let trip = Trip { start = Place.home, stop = Place.east Place.home, legs = '
                          '[Geo.origin, Geo.moveX Geo.origin 3] }\n'
                          'let dist t = t.stop.at.x - t.start.at.x\n'
                          'let lifted t = { t with start.at.y = 5 }\n'
                          'let renamed t = { t with stop = { t.stop with name = "away" } }\n'
                          'let isShop t =\n'
